// webpack.config.js

require('dotenv').config();

const path                  = require('path');
const CompressionPlugin     = require("compression-webpack-plugin");
const zlib                  = require("zlib");
const MiniCssExtractPlugin  = require("mini-css-extract-plugin");
const TerserPlugin          = require("terser-webpack-plugin");
const pathConfig            = require('./libs/editorjsGeneratePath');
const { createPostcssOptions } = require('./libs/postcssPolicy');

module.exports = {
    mode : 'production',
    watch: true,
    watchOptions:
    {
        aggregateTimeout: 600,
        stdin: true,
        ignored:
        [
            '/node_modules/',
            '/distr/',
            '/.git/',
            '/libs/',
        ],
    },
    resolve :
    {
        extensions: ['.js', '.scss']
    },
    experiments :
    {
        asset: true
    },
    optimization :
    {
        minimize: true,
        minimizer:
        [
            new TerserPlugin({
                test: /\.js(\?.*)?$/i,
                //minify: TerserPlugin.uglifyJsMinify,
                terserOptions: {
                    parse: {
                        ecma: 6
                    },
                    compress: {
                      ecma       : 5,
                      warnings   : false,
                      comparisons: false,
                      inline     : 2
                    },
                    mangle: {
                      safari10: true
                    },
                    output: {
                      ecma      : 6,
                      comments  : false,
                      ascii_only: true
                    }
                },
                parallel: true,
            }),
        ],
    },
    devtool: false,
    entry : pathConfig,
    output :
    {
        pathinfo : false,
        path : path.resolve(__dirname, 'distr'),
        publicPath : '/',
        filename : 'editorjs/[name]/js/[name].min.js',
        library: 'Checklist',
        libraryTarget: 'umd',
        libraryExport: 'default',
    },
    module :
    {
        rules :
        [
            {
                test : /\.js$/,
                exclude : /node_modules/,
                use : [
                    {
                        loader: 'babel-loader',
                    }
                ]
            },
            {
                test : /\.(scss|css)$/,
                use:
                [
                    {
                        loader : MiniCssExtractPlugin.loader,
                        options :
                        {
                            publicPath : '../../.././',
                        },
                    },
                    'css-loader',
                    {
                        loader: "postcss-loader",
                        options:
                        {
                            postcssOptions: createPostcssOptions({
                                browsers: 'last 2 versions',
                                autoprefixer: { position: true },
                            }),
                        }
                    },
                    'sass-loader',
                    {
                        loader : 'sass-resources-loader',
                        options :
                        {
                            resources :
                            [
                                process.env.DIR_GLOBAL_MIXINS,
                                process.env.DIR_GLOBAL_VARIABLES,
                                process.env.DIR_GLOBAL_SF_VARIABLES,
                                process.env.DIR_GLOBAL_SF_MIXINS,
                                process.env.DIR_GLOBAL_EXT,
                                process.env.DIR_GLOBAL_SF_EXT,
                            ],
                            sourceMap: true,
                        }
                    }
                ],
            },
        ]
    },
    plugins:[
        new MiniCssExtractPlugin(
            {
                filename: "editorjs/[name]/css/[name].min.css",
            }
        ),
        /*new CompressionPlugin({
            filename: "[path][base].br",
            algorithm: "brotliCompress",
            test: /\.(js|css|html|svg)$/,
            compressionOptions:
            {
                params:
                {
                    [zlib.constants.BROTLI_PARAM_QUALITY]: 11,
                },
            },
            threshold: 10240,
            minRatio: 0.8,
            deleteOriginalAssets: false,
        }),*/
    ]
}
